export interface ConnectorConfig {
  intercomAccessToken: string
  notionApiKey: string
  notionPageId: string
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  topic: string
  data: {
    item: {
      id: string
      state: string
    }
  }
}

export interface IntercomConversationPart {
  id: string
  body: string
  author: {
    id: string
    type: string
  }
  created_at: number
  part_type: string
  attachments: unknown[]
  redacted: boolean
}

export interface IntercomPartsResponse {
  conversation_parts: IntercomConversationPart[]
  total_count: number
  type: string
  pages: {
    next: string | null
    page: number
    per_page: number
    total_pages: number
    type: string
  }
}

export interface NotionRichTextItem {
  type: 'text'
  text: {
    content: string
  }
  annotations: {
    bold: boolean
    italic: boolean
    strikethrough: boolean
    underline: boolean
    code: boolean
    color: string
  }
  plain_text: string
  href: string | null
}

export interface NotionBlockChild {
  object: 'block'
  type: 'paragraph'
  paragraph: {
    rich_text: NotionRichTextItem[]
  }
}

export interface NotionAppendRequest {
  children: NotionBlockChild[]
}

export interface NotionAppendResponse {
  object: 'list'
  results: Array<{
    object: 'block'
    id: string
    type: 'paragraph'
    paragraph: {
      rich_text: NotionRichTextItem[]
    }
  }>
}

export interface HandleResult {
  conversationId: string
  notionBlockIds: string[]
  partsProcessed: number
}

const EMAIL_REGEX = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g
const PHONE_REGEX = /\+?[0-9\s\-]{8,}/g

function redactText(text: string): string {
  return text
    .replace(EMAIL_REGEX, '[REDACTED_EMAIL]')
    .replace(PHONE_REGEX, '[REDACTED_PHONE]')
}

function mapRoleToLabel(authorType: string): string {
  switch (authorType) {
    case 'user':
      return 'Customer'
    case 'admin':
      return 'Agent'
    case 'bot':
      return 'Bot'
    default:
      return 'Unknown'
  }
}

async function fetchAllConversationParts(
  conversationId: string,
  accessToken: string,
  fetchFn: typeof fetch
): Promise<IntercomConversationPart[]> {
  const allParts: IntercomConversationPart[] = []
  let page = 1
  const perPage = 50
  let hasNext = true

  while (hasNext) {
    const url = `https://api.intercom.io/conversations/${conversationId}/parts?page=${page}&per_page=${perPage}`
    const response = await fetchFn(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        Accept: 'application/json',
      },
    })

    if (!response.ok) {
      throw new Error(`Intercom API error: ${response.status} ${response.statusText} for GET ${url}`)
    }

    const data = (await response.json()) as IntercomPartsResponse
    allParts.push(...data.conversation_parts)

    hasNext = data.pages.next !== null
    page++
  }

  return allParts
}

async function appendToNotion(
  pageId: string,
  children: NotionBlockChild[],
  apiKey: string,
  fetchFn: typeof fetch
): Promise<string[]> {
  const url = `https://api.notion.com/v1/blocks/${pageId}/children`
  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2026-03-11',
    },
    body: JSON.stringify({ children }),
  })

  if (!response.ok) {
    throw new Error(`Notion API error: ${response.status} ${response.statusText} for PATCH ${url}`)
  }

  const data = (await response.json()) as NotionAppendResponse
  return data.results.map((block) => block.id)
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.topic) {
    throw new Error('Missing required field: topic')
  }
  if (payload.topic !== 'conversation.updated') {
    throw new Error(`Unsupported topic: ${payload.topic}, expected conversation.updated`)
  }
  if (!payload.data?.item?.id) {
    throw new Error('Missing required field: data.item.id')
  }
  if (!payload.data?.item?.state) {
    throw new Error('Missing required field: data.item.state')
  }
  if (payload.data.item.state !== 'closed') {
    throw new Error(`Conversation state is ${payload.data.item.state}, expected closed`)
  }

  const conversationId = payload.data.item.id

  if (!config.intercomAccessToken) {
    throw new Error('Missing config: intercomAccessToken')
  }
  if (!config.notionApiKey) {
    throw new Error('Missing config: notionApiKey')
  }
  if (!config.notionPageId) {
    throw new Error('Missing config: notionPageId')
  }

  const parts = await fetchAllConversationParts(conversationId, config.intercomAccessToken, fetchFn)

  const children: NotionBlockChild[] = parts.map((part) => {
    const redactedBody = redactText(part.body)
    const authorLabel = mapRoleToLabel(part.author.type)

    return {
      object: 'block',
      type: 'paragraph',
      paragraph: {
        rich_text: [
          {
            type: 'text',
            text: {
              content: `${authorLabel}: ${redactedBody}`,
            },
            annotations: {
              bold: false,
              italic: false,
              strikethrough: false,
              underline: false,
              code: false,
              color: 'default',
            },
            plain_text: `${authorLabel}: ${redactedBody}`,
            href: null,
          },
        ],
      },
    }
  })

  const notionBlockIds = await appendToNotion(config.notionPageId, children, config.notionApiKey, fetchFn)

  return {
    conversationId,
    notionBlockIds,
    partsProcessed: parts.length,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, IntercomWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      intercomAccessToken: 'test-intercom-token',
      notionApiKey: 'test-notion-key',
      notionPageId: 'test-page-id',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.conversationId).toBe('1911149811')
    expect(result.partsProcessed).toBeGreaterThan(0)
    expect(result.notionBlockIds.length).toBeGreaterThan(0)
  })
})

describe('handle', () => {
  it('processes conversation parts and appends to Notion on happy path', async () => {
    const intercomPartsResponse = {
      conversation_parts: [
        {
          id: 'part-1',
          body: 'Hello, my email is test@example.com',
          author: { id: 'user-1', type: 'user' },
          created_at: 1234567890,
          part_type: 'comment',
          attachments: [],
          redacted: false,
        },
        {
          id: 'part-2',
          body: 'Call me at +1-555-123-4567',
          author: { id: 'admin-1', type: 'admin' },
          created_at: 1234567891,
          part_type: 'comment',
          attachments: [],
          redacted: false,
        },
      ],
      total_count: 2,
      type: 'conversation_part.list',
      pages: {
        next: null,
        page: 1,
        per_page: 50,
        total_pages: 1,
        type: 'pages',
      },
    }

    const notionResponse = {
      object: 'list',
      results: [
        { object: 'block', id: 'notion-block-1', type: 'paragraph', paragraph: { rich_text: [] } },
        { object: 'block', id: 'notion-block-2', type: 'paragraph', paragraph: { rich_text: [] } },
      ],
    }

    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/conversations/') && req.url.includes('/parts')) {
        return jsonResponse(intercomPartsResponse)
      }
      if (req.url.includes('/blocks/') && req.url.includes('/children')) {
        return jsonResponse(notionResponse)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'test-intercom-token',
      notionApiKey: 'test-notion-key',
      notionPageId: 'test-page-id',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: 'conv-123', state: 'closed' } },
    }

    const result = await handle(payload, config)

    expect(result.conversationId).toBe('conv-123')
    expect(result.partsProcessed).toBe(2)
    expect(result.notionBlockIds).toEqual(['notion-block-1', 'notion-block-2'])

    expect(calls).toHaveLength(2)

    const intercomCall = calls[0]
    expect(intercomCall.method).toBe('GET')
    expect(intercomCall.url).toBe('https://api.intercom.io/conversations/conv-123/parts?page=1&per_page=50')
    expect(intercomCall.headers.get('authorization')).toBe('Bearer test-intercom-token')

    const notionCall = calls[1]
    expect(notionCall.method).toBe('PATCH')
    expect(notionCall.url).toBe('https://api.notion.com/v1/blocks/test-page-id/children')
    expect(notionCall.headers.get('authorization')).toBe('Bearer test-notion-key')
    expect(notionCall.headers.get('notion-version')).toBe('2026-03-11')

    const notionBody = notionCall.json as { children: Array<{ paragraph: { rich_text: Array<{ text: { content: string } }> } }> }
    expect(notionBody.children).toHaveLength(2)
    expect(notionBody.children[0].paragraph.rich_text[0].text.content).toContain('Customer:')
    expect(notionBody.children[0].paragraph.rich_text[0].text.content).toContain('[REDACTED_EMAIL]')
    expect(notionBody.children[1].paragraph.rich_text[0].text.content).toContain('Agent:')
    expect(notionBody.children[1].paragraph.rich_text[0].text.content).toContain('[REDACTED_PHONE]')
  })

  it('uses bearer auth for both Intercom and Notion', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/parts')) {
        return jsonResponse({
          conversation_parts: [],
          total_count: 0,
          type: 'conversation_part.list',
          pages: { next: null, page: 1, per_page: 50, total_pages: 1, type: 'pages' },
        })
      }
      if (req.url.includes('/children')) {
        return jsonResponse({ object: 'list', results: [] })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'intercom-secret',
      notionApiKey: 'notion-secret',
      notionPageId: 'page-123',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: 'conv-1', state: 'closed' } },
    }

    await handle(payload, config)

    expect(calls[0].headers.get('authorization')).toBe('Bearer intercom-secret')
    expect(calls[1].headers.get('authorization')).toBe('Bearer notion-secret')
  })

  it('maps fields correctly: parts to rich_text with role mapping', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/parts')) {
        return jsonResponse({
          conversation_parts: [
            {
              id: 'p1',
              body: 'User message',
              author: { id: 'u1', type: 'user' },
              created_at: 1,
              part_type: 'comment',
              attachments: [],
              redacted: false,
            },
            {
              id: 'p2',
              body: 'Admin reply',
              author: { id: 'a1', type: 'admin' },
              created_at: 2,
              part_type: 'comment',
              attachments: [],
              redacted: false,
            },
            {
              id: 'p3',
              body: 'Bot response',
              author: { id: 'b1', type: 'bot' },
              created_at: 3,
              part_type: 'comment',
              attachments: [],
              redacted: false,
            },
          ],
          total_count: 3,
          type: 'conversation_part.list',
          pages: { next: null, page: 1, per_page: 50, total_pages: 1, type: 'pages' },
        })
      }
      if (req.url.includes('/children')) {
        return jsonResponse({ object: 'list', results: [{ object: 'block', id: 'b1', type: 'paragraph', paragraph: { rich_text: [] } }] })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: 'conv-1', state: 'closed' } },
    }

    await handle(payload, config)

    const notionBody = calls[1].json as { children: Array<{ paragraph: { rich_text: Array<{ text: { content: string } }> } }> }
    expect(notionBody.children[0].paragraph.rich_text[0].text.content).toBe('Customer: User message')
    expect(notionBody.children[1].paragraph.rich_text[0].text.content).toBe('Agent: Admin reply')
    expect(notionBody.children[2].paragraph.rich_text[0].text.content).toBe('Bot: Bot response')
  })

  it('throws on missing required field: topic', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload = { data: { item: { id: '1', state: 'closed' } } } as unknown as IntercomWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: topic')
  })

  it('throws on missing required field: data.item.id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload = { topic: 'conversation.updated', data: { item: { state: 'closed' } } } as unknown as IntercomWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: data.item.id')
  })

  it('throws on missing required field: data.item.state', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload = { topic: 'conversation.updated', data: { item: { id: '1' } } } as unknown as IntercomWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: data.item.state')
  })

  it('throws when conversation state is not closed', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: '1', state: 'open' } },
    }

    await expect(handle(payload, config)).rejects.toThrow('Conversation state is open, expected closed')
  })

  it('throws when config is missing intercomAccessToken', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config = { notionApiKey: 'key', notionPageId: 'page', fetch } as unknown as ConnectorConfig

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: '1', state: 'closed' } },
    }

    await expect(handle(payload, config)).rejects.toThrow('Missing config: intercomAccessToken')
  })

  it('throws when config is missing notionApiKey', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config = { intercomAccessToken: 'token', notionPageId: 'page', fetch } as unknown as ConnectorConfig

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: '1', state: 'closed' } },
    }

    await expect(handle(payload, config)).rejects.toThrow('Missing config: notionApiKey')
  })

  it('throws when config is missing notionPageId', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config = { intercomAccessToken: 'token', notionApiKey: 'key', fetch } as unknown as ConnectorConfig

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: '1', state: 'closed' } },
    }

    await expect(handle(payload, config)).rejects.toThrow('Missing config: notionPageId')
  })

  it('throws on non-2xx Intercom API response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: '1', state: 'closed' } },
    }

    await expect(handle(payload, config)).rejects.toThrow('Intercom API error: 401 Unauthorized for GET https://api.intercom.io/conversations/1/parts?page=1&per_page=50')
  })

  it('throws on non-2xx Notion API response', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/parts')) {
        return jsonResponse({
          conversation_parts: [],
          total_count: 0,
          type: 'conversation_part.list',
          pages: { next: null, page: 1, per_page: 50, total_pages: 1, type: 'pages' },
        })
      }
      return jsonResponse({ error: 'forbidden' }, 403)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: '1', state: 'closed' } },
    }

    await expect(handle(payload, config)).rejects.toThrow('Notion API error: 403 Forbidden for PATCH https://api.notion.com/v1/blocks/page/children')
  })

  it('handles pagination across multiple pages', async () => {
    const page1Response = {
      conversation_parts: [
        { id: 'p1', body: 'Page 1 part', author: { id: 'u1', type: 'user' }, created_at: 1, part_type: 'comment', attachments: [], redacted: false },
      ],
      total_count: 2,
      type: 'conversation_part.list',
      pages: { next: 'https://api.intercom.io/conversations/conv-1/parts?per_page=50&page=2', page: 1, per_page: 50, total_pages: 2, type: 'pages' },
    }

    const page2Response = {
      conversation_parts: [
        { id: 'p2', body: 'Page 2 part', author: { id: 'a1', type: 'admin' }, created_at: 2, part_type: 'comment', attachments: [], redacted: false },
      ],
      total_count: 2,
      type: 'conversation_part.list',
      pages: { next: null, page: 2, per_page: 50, total_pages: 2, type: 'pages' },
    }

    let pageCallCount = 0
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/parts')) {
        pageCallCount++
        if (pageCallCount === 1) return jsonResponse(page1Response)
        if (pageCallCount === 2) return jsonResponse(page2Response)
        return jsonResponse({ error: 'too many pages' }, 500)
      }
      if (req.url.includes('/children')) {
        return jsonResponse({ object: 'list', results: [{ object: 'block', id: 'b1', type: 'paragraph', paragraph: { rich_text: [] } }] })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: 'conv-1', state: 'closed' } },
    }

    const result = await handle(payload, config)

    expect(result.partsProcessed).toBe(2)
    expect(calls.filter((c) => c.url.includes('/parts'))).toHaveLength(2)
    expect(calls[0].url).toContain('page=1')
    expect(calls[1].url).toContain('page=2')
  })

  it('redacts multiple emails and phones in a single message', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/parts')) {
        return jsonResponse({
          conversation_parts: [
            {
              id: 'p1',
              body: 'Contact me at john.doe@example.com or jane@test.co.uk, phone +44 20 7946 1234 or 555-123-4567',
              author: { id: 'u1', type: 'user' },
              created_at: 1,
              part_type: 'comment',
              attachments: [],
              redacted: false,
            },
          ],
          total_count: 1,
          type: 'conversation_part.list',
          pages: { next: null, page: 1, per_page: 50, total_pages: 1, type: 'pages' },
        })
      }
      if (req.url.includes('/children')) {
        return jsonResponse({ object: 'list', results: [{ object: 'block', id: 'b1', type: 'paragraph', paragraph: { rich_text: [] } }] })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionPageId: 'page',
      fetch,
    }

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.updated',
      data: { item: { id: 'conv-1', state: 'closed' } },
    }

    await handle(payload, config)

    const notionBody = calls[1].json as { children: Array<{ paragraph: { rich_text: Array<{ text: { content: string } }> } }> }
    const content = notionBody.children[0].paragraph.rich_text[0].text.content
    expect(content).toContain('[REDACTED_EMAIL]')
    expect(content).toContain('[REDACTED_PHONE]')
    expect(content).not.toContain('john.doe@example.com')
    expect(content).not.toContain('jane@test.co.uk')
    expect(content).not.toContain('+44 20 7946 1234')
    expect(content).not.toContain('555-123-4567')
  })
})

