const EMAIL_REGEX = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g
const PHONE_REGEX = /\+?[0-9\s\-]{8,}/g

function redactText(text: string): string {
  return text
    .replace(EMAIL_REGEX, '[REDACTED_EMAIL]')
    .replace(PHONE_REGEX, '[REDACTED_PHONE]')
}

function mapRoleToLabel(authorType: string): string {
  switch (authorType) {
    case 'user':
      return 'Customer'
    case 'admin':
      return 'Agent'
    case 'bot':
      return 'Bot'
    default:
      return 'Unknown'
  }
}

async function fetchAllConversationParts(
  conversationId: string,
  accessToken: string,
  fetchFn: typeof fetch
): Promise<IntercomConversationPart[]> {
  const allParts: IntercomConversationPart[] = []
  let page = 1
  const perPage = 50
  let hasNext = true

  while (hasNext) {
    const url = `https://api.intercom.io/conversations/${conversationId}/parts?page=${page}&per_page=${perPage}`
    const response = await fetchFn(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        Accept: 'application/json',
      },
    })

    if (!response.ok) {
      throw new Error(`Intercom API error: ${response.status} ${response.statusText} for GET ${url}`)
    }

    const data = (await response.json()) as IntercomPartsResponse
    allParts.push(...data.conversation_parts)

    hasNext = data.pages.next !== null && page < data.pages.total_pages
    page++
  }

  return allParts
}

async function appendToNotion(
  pageId: string,
  children: NotionBlockChild[],
  apiKey: string,
  fetchFn: typeof fetch
): Promise<string[]> {
  const url = `https://api.notion.com/v1/blocks/${pageId}/children`
  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2026-03-11',
    },
    body: JSON.stringify({ children }),
  })

  if (!response.ok) {
    throw new Error(`Notion API error: ${response.status} ${response.statusText} for PATCH ${url}`)
  }

  const data = (await response.json()) as NotionAppendResponse
  return data.results.map((block) => block.id)
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.topic) {
    throw new Error('Missing required field: topic')
  }
  if (payload.topic !== 'conversation.updated') {
    throw new Error(`Unsupported topic: ${payload.topic}, expected conversation.updated`)
  }
  if (!payload.data?.item?.id) {
    throw new Error('Missing required field: data.item.id')
  }
  if (!payload.data?.item?.state) {
    throw new Error('Missing required field: data.item.state')
  }
  if (payload.data.item.state !== 'closed') {
    throw new Error(`Conversation state is ${payload.data.item.state}, expected closed`)
  }

  const conversationId = payload.data.item.id

  if (!config.intercomAccessToken) {
    throw new Error('Missing config: intercomAccessToken')
  }
  if (!config.notionApiKey) {
    throw new Error('Missing config: notionApiKey')
  }
  if (!config.notionPageId) {
    throw new Error('Missing config: notionPageId')
  }

  const parts = await fetchAllConversationParts(conversationId, config.intercomAccessToken, fetchFn)

  const children: NotionBlockChild[] = parts.map((part) => {
    const redactedBody = redactText(part.body)
    const authorLabel = mapRoleToLabel(part.author.type)

    return {
      object: 'block',
      type: 'paragraph',
      paragraph: {
        rich_text: [
          {
            type: 'text',
            text: {
              content: `${authorLabel}: ${redactedBody}`,
            },
            annotations: {
              bold: false,
              italic: false,
              strikethrough: false,
              underline: false,
              code: false,
              color: 'default',
            },
            plain_text: `${authorLabel}: ${redactedBody}`,
            href: null,
          },
        ],
      },
    }
  })

  const notionBlockIds = await appendToNotion(config.notionPageId, children, config.notionApiKey, fetchFn)

  return {
    conversationId,
    notionBlockIds,
    partsProcessed: parts.length,
  }
}

